import { readFileSync } from 'fs';
const input = readFileSync(0, 'utf8');
export function slugify(text) {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

for (const line of input.trim().split('\n')) {
  console.log(slugify(line));
}
